-- Engine tests: ports of the web engine's tests (src/game/engine/engine.test.ts) plus parity
-- against fixtures generated by the real TypeScript engine (tests/fixtures/parity.lua).
local root, testdir = ...
local H = dofile(testdir .. "/harness.lua")
local ns = H.load(root, { "Engine/Prng.lua", "Engine/Pieces.lua", "Engine/Engine.lua", "Engine/Input.lua", "Engine/Verify.lua" })
local E, P, Prng, Input = ns.Engine, ns.Pieces, ns.Prng, ns.Input
local it, eq, ok, describe = H.it, H.eq, H.ok, H.describe

local function boardWith(s, filled) -- filled[y] = { gap x, ... }
  local w = s.config.width
  for y, gaps in pairs(filled) do
    local g = {}
    for _, x in ipairs(gaps) do g[x] = true end
    for x = 0, w - 1 do if not g[x] then s.board[y * w + x + 1] = 8 end end
  end
end
local function run(s, ...) for i = 1, select("#", ...) do E.applyInput(s, (select(i, ...))) end return s end
local function barSeed(prefix)
  for i = 0, 499 do
    local s = E.createGame(prefix .. i)
    if s.active.id == "bar" then return s end
  end
  error("no bar seed")
end
local function rowsOf(s) return s.config.height + s.config.hiddenRows end

describe("prng", function()
  local fx = dofile(os.getenv("SR_FIXTURES") or (testdir .. "/fixtures/parity.lua"))
  it("hashString and mulberry32 match the web engine bit for bit", function()
    for _, v in ipairs(fx.prngVectors) do
      eq(Prng.hashString(v.str), v.hash, "hash of " .. v.str)
      local st = Prng.hashString(v.str)
      for i = 1, #v.seq do
        local r
        r, st = Prng.nextRandom(st)
        eq(math.floor(r * 1e9), v.seq[i], v.str .. " value " .. i)
      end
    end
  end)
end)

describe("determinism", function()
  it("same seed produces the same piece sequence", function()
    local a, b = E.createGame("abc"), E.createGame("abc")
    eq(table.concat(a.queue, ","), table.concat(b.queue, ","))
    eq(a.active.id, b.active.id)
  end)
  it("bag randomizer deals each of the 7 pieces exactly once per bag", function()
    local s = E.createGame("bag-test")
    local seen = { s.active.id }
    for i = 1, 6 do seen[#seen + 1] = s.queue[i] end
    table.sort(seen)
    local ids = {}
    for i, v in ipairs(P.IDS) do ids[i] = v end
    table.sort(ids)
    eq(table.concat(seen, ","), table.concat(ids, ","))
  end)
  it("replay of a live game gives the same hash; serialize/deserialize round-trips", function()
    local s = E.createGame("live-1")
    local acts = { "left", "rotateCW", "hardDrop", "right", "right", "softDrop", "hold", "hardDrop", "rotateCCW", "hardDrop" }
    for i = 1, 400 do
      if i % 13 == 0 then E.applyInput(s, acts[(i / 13) % #acts + 1]) end
      E.tick(s)
    end
    local d = E.deserializeLog(E.serializeLog(s))
    ok(d, "deserialize")
    eq(d.seed, "live-1")
    eq(d.ticks, s.tick)
    local r = E.replay(d.seed, { startLevel = d.startLevel }, d.log, d.ticks)
    eq(E.hashState(r), E.hashState(s))
  end)
  it("rejects out-of-order input logs", function()
    local okc = pcall(E.replay, "x", {}, { 5, 0, 3, 1 }, 10)
    eq(okc, false)
  end)
end)

describe("line clear scoring", function()
  it("quad at level 1 = 800 plus hard-drop points", function()
    local s = barSeed("q")
    local h = rowsOf(s)
    boardWith(s, { [h - 1] = { 9 }, [h - 2] = { 9 }, [h - 3] = { 9 }, [h - 4] = { 9 } })
    run(s, "rotateCW", "right", "right", "right", "right", "right")
    local before = s.score
    E.applyInput(s, "hardDrop")
    eq(s.lines, 4); eq(s.clears.quad, 1); eq(s.lastClear.points, 800)
    local dropPts = s.score - before - 800
    ok(dropPts > 0 and dropPts % 2 == 0, "2 points per hard-dropped row")
    for i = #s.board - 39, #s.board do eq(s.board[i], 0) end
  end)
  it("single/double/triple base values scale with level", function()
    for n, base in ipairs({ 100, 300, 500 }) do
      local s = barSeed("lvl")
      s.level = 3
      local h = rowsOf(s)
      local spec = {}
      for r = 0, n - 1 do spec[h - 1 - r] = { 9 } end
      boardWith(s, spec)
      run(s, "rotateCW", "right", "right", "right", "right", "right", "hardDrop")
      eq(s.lines, n); eq(s.lastClear.points, base * 3)
    end
  end)
  it("back-to-back quads get a 1.5x bonus and combos add 50 x combo x level", function()
    local s = barSeed("b2b")
    s.backToBack, s.combo = true, 0
    local h = rowsOf(s)
    boardWith(s, { [h - 1] = { 9 }, [h - 2] = { 9 }, [h - 3] = { 9 }, [h - 4] = { 9 } })
    run(s, "rotateCW", "right", "right", "right", "right", "right", "hardDrop")
    eq(s.lastClear.backToBack, true); eq(s.lastClear.combo, 1); eq(s.lastClear.points, 1250)
  end)
  it("a non-clearing lock resets the combo", function()
    local s = E.createGame("combo-reset")
    s.combo = 3
    E.applyInput(s, "hardDrop")
    eq(s.combo, -1)
  end)
  it("level increases every 10 lines", function()
    local s = barSeed("levelup")
    s.lines = 8
    local h = rowsOf(s)
    boardWith(s, { [h - 1] = { 9 }, [h - 2] = { 9 } })
    run(s, "rotateCW", "right", "right", "right", "right", "right", "hardDrop")
    eq(s.lines, 10); eq(s.level, 2)
  end)
end)

describe("rotation and wall kicks", function()
  it("four CW rotations return to the original orientation", function()
    for _, id in ipairs(P.IDS) do
      local shapes = P.SHAPES[id]
      local function key(c) local t = {} for i, v in ipairs(c) do t[i] = v[1] .. ":" .. v[2] end table.sort(t) return table.concat(t, " ") end
      eq(#shapes, 4, id)
      ok(key(shapes[1]) ~= nil)
    end
    local s = E.createGame("rot")
    local a0 = s.active.rotation
    run(s, "rotateCW", "rotateCW", "rotateCW", "rotateCW")
    eq(s.active.rotation, a0)
  end)
  it("kicks a piece off the left wall instead of failing to rotate", function()
    for i = 0, 200 do
      local s = E.createGame("kick" .. i)
      if s.active.id == "tee" then
        run(s, "rotateCW")
        for _ = 1, 6 do E.applyInput(s, "left") end
        local x = s.active.x
        E.applyInput(s, "rotateCW")
        eq(s.active.rotation, 2, "rotated")
        ok(s.active.x >= x, "pushed right or stayed")
        return
      end
    end
    error("no tee seed")
  end)
  it("long bar kicks off the left wall", function()
    local s = barSeed("barkick")
    run(s, "rotateCW")
    for _ = 1, 8 do E.applyInput(s, "left") end
    E.applyInput(s, "rotateCW")
    eq(s.active.rotation, 2)
    for _, c in ipairs(E.cellsOf(s.active)) do ok(c[1] >= 0, "inside board") end
  end)
  it("rotation fails cleanly when every kick is blocked", function()
    local s = barSeed("blocked")
    for i = 1, #s.board do s.board[i] = 8 end
    local w = s.config.width
    for _, c in ipairs(E.cellsOf(s.active)) do if c[2] >= 0 then s.board[c[2] * w + c[1] + 1] = 0 end end
    local before = s.active.rotation
    E.applyInput(s, "rotateCW")
    eq(s.active.rotation, before)
  end)
  it("cube does not change shape when rotated", function()
    for i = 0, 200 do
      local s = E.createGame("cube" .. i)
      if s.active.id == "cube" then
        local before = E.cellsOf(s.active)
        E.applyInput(s, "rotateCW")
        local after = E.cellsOf(s.active)
        for k = 1, 4 do eq(after[k][1], before[k][1]); eq(after[k][2], before[k][2]) end
        return
      end
    end
    error("no cube seed")
  end)
end)

describe("hold", function()
  it("swaps to the next piece and can only be used once per piece", function()
    local s = E.createGame("hold-test")
    local first, nxt = s.active.id, s.queue[1]
    E.applyInput(s, "hold")
    eq(s.hold, first); eq(s.active.id, nxt); eq(s.holdUsed, true)
    local id = s.active.id
    E.applyInput(s, "hold")
    eq(s.active.id, id, "second hold ignored")
    E.applyInput(s, "hardDrop")
    eq(s.holdUsed, false)
    E.applyInput(s, "hold")
    eq(s.active.id, first, "held piece comes back")
  end)
end)

describe("game over", function()
  it("block-out: spawning into occupied cells ends the game", function()
    local s = E.createGame("blockout")
    local w = s.config.width
    for y = 2, 4 do for x = 0, w - 2 do s.board[y * w + x + 1] = 8 end end
    local guard = 0
    while not s.gameOver and guard < 50 do E.applyInput(s, "hardDrop"); guard = guard + 1 end
    eq(s.gameOver, true); eq(s.active, nil)
  end)
  it("ignores inputs and ticks after game over", function()
    local s = E.createGame("over")
    s.gameOver = true
    local h = E.hashState(s)
    E.applyInput(s, "left"); E.tick(s)
    eq(E.hashState(s), h)
  end)
  it("gravity eventually locks pieces without any input", function()
    local s = E.createGame("gravity", { startLevel = 15 })
    for _ = 1, 2000 do if s.gameOver then break end E.tick(s) end
    ok(s.piecesPlaced > 5)
  end)
  it("board cell values map to piece ids", function()
    for i, id in ipairs(P.IDS) do eq(P.cellValue(id), i) end
  end)
end)

describe("input handler (DAS/ARR like the web game)", function()
  it("tap moves once; holding repeats after 10 ticks every 2 ticks", function()
    local inp = Input.new()
    inp:press("left")
    local counts = {}
    for t = 1, 20 do
      local n = 0
      for _, a in ipairs(inp:drain()) do if a == "left" then n = n + 1 end end
      counts[t] = n
    end
    eq(counts[1], 1, "initial press")
    for t = 2, 9 do eq(counts[t], 0, "tick " .. t) end
    eq(counts[10], 1); eq(counts[11], 0); eq(counts[12], 1)
  end)
  it("releasing one direction falls back to the other held one", function()
    local inp = Input.new()
    inp:press("left"); inp:press("right"); inp:release("right")
    eq(inp.heldDir, "left")
    inp:releaseAll()
    eq(inp.heldDir, nil); eq(#inp:drain(), 0)
  end)
end)

-- Fixtures can be swapped for a freshly generated set (tools/parity/check_web.sh) via SR_FIXTURES.
local FIXTURES = os.getenv("SR_FIXTURES") or (testdir .. "/fixtures/parity.lua")

describe("rules fingerprint (every gameplay constant vs the web engine)", function()
  local R = dofile(FIXTURES).rules
  local function same(a, b, path)
    if type(b) == "table" then
      ok(type(a) == "table", path .. ": missing in Lua")
      for k, v in pairs(b) do same(a[k], v, path .. "." .. tostring(k)) end
      for k in pairs(a) do if b[k] == nil then error(path .. "." .. tostring(k) .. ": extra in Lua", 0) end end
    else
      if a ~= b then error(path .. ": web " .. tostring(b) .. " / lua " .. tostring(a), 0) end
    end
  end
  it("engine version, tick rate, actions, piece ids", function()
    eq(E.ENGINE_VERSION, R.engineVersion, "ENGINE_VERSION")
    eq(E.TICKS_PER_SECOND, R.ticksPerSecond, "TICKS_PER_SECOND")
    same(E.INPUT_ACTIONS, R.inputActions, "inputActions")
    same(P.IDS, R.pieceIds, "pieceIds")
  end)
  it("board config, lock delay, preview count, lines per level", function()
    same(E.DEFAULT_CONFIG, R.config, "config")
  end)
  it("scoring: line points, back-to-back, combo, drop points", function()
    same(E.LINE_POINTS, R.linePoints, "linePoints")
    eq(E.B2B_MULTIPLIER, R.b2bMultiplier, "b2b"); eq(E.COMBO_POINTS, R.comboPoints, "combo")
    eq(E.SOFT_DROP_POINTS, R.softDropPoints, "soft"); eq(E.HARD_DROP_POINTS, R.hardDropPoints, "hard")
  end)
  it("speed curve for levels 1-25", function()
    for lvl, g in ipairs(R.gravity) do eq(E.gravityTicks(lvl), g, "gravity level " .. lvl) end
  end)
  it("input handling (DAS / ARR / soft drop repeat)", function()
    same(Input.HANDLING, R.handling, "handling")
  end)
  it("piece shapes in all rotations", function()
    for id, rots in pairs(R.shapes) do
      for r, cells in ipairs(rots) do same(P.SHAPES[id][r], cells, "shape " .. id .. " rot " .. (r - 1)) end
    end
  end)
  it("web 1v1 match rules: time cap, countdown, input limits, reconnect grace, clock slack", function()
    local Mr = R.match
    ok(Mr and Mr.timeCapMs, "fixtures contain the web match rules")
    local V = ns.Verify
    eq(V.TIME_CAP_MS, Mr.timeCapMs, "match.timeCapMs"); eq(V.COUNTDOWN_MS, Mr.countdownMs, "match.countdownMs")
    eq(V.MAX_INPUTS_PER_TICK, Mr.maxInputsPerTick, "match.maxInputsPerTick")
    eq(V.MAX_INPUTS_PER_SECOND, Mr.maxInputsPerSecond, "match.maxInputsPerSecond")
    eq(V.RECONNECT_GRACE_MS, Mr.reconnectGraceMs, "match.reconnectGraceMs")
    eq(V.CLOCK_SLACK_MS, Mr.clockSlackMs, "match.clockSlackMs")
  end)
  it("wall kicks for every piece and rotation", function()
    for key, list in pairs(R.kicks) do
      local id, f, t = key:match("^(%w+):(%d)>(%d)$")
      same(P.getKicks(id, tonumber(f), tonumber(t)), list, "kicks " .. key)
    end
  end)
end)

describe("parity with the web engine", function()
  local fx = dofile(FIXTURES)
  for _, c in ipairs(fx.cases) do
    it(c.name .. " (" .. c.seed .. ", " .. (#c.log / 2) .. " inputs)", function()
      for _, cp in ipairs(c.checkpoints) do
        local s = E.replay(c.seed, {}, c.log, cp["until"])
        local where = c.name .. " @" .. cp["until"]
        eq(s.score, cp.score, where .. " score")
        eq(s.lines, cp.lines, where .. " lines")
        eq(s.level, cp.level, where .. " level")
        eq(s.piecesPlaced, cp.pieces, where .. " pieces")
        eq(s.gameOver, cp.gameOver, where .. " gameOver")
        eq(E.hashState(s), cp.hash, where .. " hashState")
      end
    end)
  end
end)

return H
